<?php
// `wp eval-file` runs after wp-config has been generated by the web container.
// Core installation is performed separately because this file needs WordPress.
if (!defined('WP_CLI') || !WP_CLI || wp_get_environment_type() !== 'local') {
    throw new RuntimeException('Local WP-CLI only.');
}
foreach (['woocommerce' => '11.1.1', 'woocommerce-paypal-payments' => '4.1.3'] as $slug => $version) {
    if (is_dir(WP_PLUGIN_DIR . '/' . $slug)) {
        $installed = get_plugin_data(WP_PLUGIN_DIR . '/' . $slug . '/' . $slug . '.php', false, false);
        if (($installed['Version'] ?? '') !== $version) {
            WP_CLI::error('Installed ' . $slug . ' differs from the locked version; review the upgrade instead of overwriting it.');
        }
        WP_CLI::runcommand('plugin activate ' . $slug);
    } else {
        WP_CLI::runcommand('plugin install /workspace/packages/' . $slug . '.' . $version . '.zip --activate');
    }
}
WP_CLI::runcommand('eval-file /workspace/scripts/configure-local.php');
WP_CLI::runcommand('eval-file /workspace/scripts/apply-local-shipping-policy.php');
